self.addEventListener("push",t=>{let i;if(t.data){try{i=t.data.json()}catch{return}t.waitUntil(self.registration.showNotification(i.title,{body:i.body,icon:i.icon??"/icons/icon-192x192.png",badge:"/icons/icon-192x192.png",data:i.data,vibrate:[200,100,200]}))}}),self.addEventListener("notificationclick",t=>{t.notification.close();let i=t.notification.data?.url??"/account/orders";t.waitUntil(self.clients.matchAll({type:"window",includeUncontrolled:!0}).then(t=>{for(let n of t)if(n.url.endsWith(i)&&"focus"in n)return n.focus();if(self.clients.openWindow)return self.clients.openWindow(i)}))});